WITH matched_keys AS (SELECT order_id FROM order_items EXCEPT ALL SELECT order_id FROM order_items WHERE product_id IN (14, 36, 38)), kept_rows AS (SELECT s.* FROM order_items s JOIN matched_keys k ON s.order_id = k.order_id) SELECT product_id, CASE WHEN unit_price >= 340 THEN 'PREMIUM' ELSE 'STANDARD' END AS unit_price_tier, PERCENTILE_APPROX(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, APPROX_PERCENTILE(unit_price, ARRAY(0.25, 0.5, 0.75)) AS unit_price_quartiles, ROUND(AVG(quantity), 2) AS avg_quantity, AVG(unit_price) AS avg_unit_price, AVG(unit_price) AS avg_unit_price_2, GROUPING(product_id) AS grouping_id FROM kept_rows GROUP BY CUBE (product_id, CASE WHEN unit_price >= 340 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY unit_price_tier
